169	  const ariaChecked = 'ariaChecked' in props ? props.ariaChecked : undefined;
170	
171	  return (
172	    <ChakraButton
173	      type={ariaDisabled ? 'button' : type}
174	      isDisabled={disabled}
175	      aria-disabled={ariaDisabledAttr}
176	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
177	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
178	      aria-label={ariaLabel ?? label}
179	      aria-describedby={ariaDescribedBy}
180	      role={role}
181	      aria-checked={ariaChecked}
182	      onClick={handleClick}
183	      variant={chakraVariant}
184	      size={size}
185	      width={props.fullWidth ? '100%' : undefined}
186	      style={style}
187	      sx={sx}
188	    >
189	      {props.iconLeading && (
190	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
191	          {props.iconLeading}
192	        </chakra.span>
193	      )}
